import React, { useEffect, useState } from 'react';
import API from '../api/axios';

const ManageComplaints = () => {
  const [complaints, setComplaints] = useState([]);

  const fetchComplaints = () => {
    API.get('/admin/complaints')
      .then(res => setComplaints(res.data))
      .catch(err => console.error(err));
  };

  useEffect(() => { fetchComplaints(); }, []);

  const handleUpdate = async (id, status, assignedTo) => {
    try {
      await API.put(`/admin/complaints/${id}`, { status, assignedTo });
      alert('Complaint status updated successfully!');
      fetchComplaints();
    } catch (err) {
      alert('Error updating complaint.');
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <h1 className="text-2xl font-bold mb-6 text-slate-900">Manage Student Complaints</h1>

      <div className="bg-white rounded-xl shadow border overflow-x-auto">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-slate-100 text-slate-700 text-sm">
              <th className="p-4">Student</th>
              <th className="p-4">Category</th>
              <th className="p-4">Title & Location</th>
              <th className="p-4">Assigned To</th>
              <th className="p-4">Status</th>
              <th className="p-4">Action</th>
            </tr>
          </thead>
          <tbody className="divide-y text-sm">
            {complaints.map((c) => (
              <tr key={c._id} className="hover:bg-slate-50">
                <td className="p-4">
                  <div className="font-bold">{c.userId?.name}</div>
                  <div className="text-xs text-slate-500">{c.userId?.rollNo}</div>
                </td>
                <td className="p-4 font-semibold text-sky-600">{c.category}</td>
                <td className="p-4">
                  <div className="font-bold text-slate-800">{c.title}</div>
                  <div className="text-xs text-slate-500">📍 {c.location}</div>
                </td>
                <td className="p-4">
                  <input
                    type="text"
                    defaultValue={c.assignedTo}
                    className="border rounded p-1 text-xs"
                    onBlur={(e) => handleUpdate(c._id, c.status, e.target.value)}
                  />
                </td>
                <td className="p-4">
                  <select
                    value={c.status}
                    onChange={(e) => handleUpdate(c._id, e.target.value, c.assignedTo)}
                    className="border rounded p-1 text-xs bg-white font-semibold"
                  >
                    <option value="Pending">Pending</option>
                    <option value="In-Progress">In-Progress</option>
                    <option value="Resolved">Resolved</option>
                  </select>
                </td>
                <td className="p-4">
                  {c.image && (
                    <a href={`http://localhost:5000${c.image}`} target="_blank" rel="noreferrer" className="text-sky-600 underline text-xs">
                      View Image
                    </a>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default ManageComplaints;
